     */
    #[Override]
    public function replay(string $eventsUrl, ?int $lastEventId, callable $onEvent): ?array
    {
        $this->replays[] = [$eventsUrl, $lastEventId];

        foreach ($this->events as $event) {
            $onEvent($event['type'], $event['payload'], $event['id']);
